        update(false);
        const again = root.querySelector('.show-more[data-section="' + key + '"]');
        if (again) again.focus({ preventScroll: true });
      });
    });

    root.querySelectorAll(".row").forEach((btn) => {
      btn.addEventListener("click", () => selectRecord(btn.getAttribute("data-id")));
    });
