1	"use strict";
2	/*
3	 * app.js — The Open Collection · Natural History Index
4	 *
5	 * Pattern: PAT-LIST-DETAIL (selection-bound contextual inspector).
6	 * Single app state: { query, facet sets, selection, per-section windows }.
7	 * The results context (query, filters, counts, scroll) is never reset by
8	 * inspecting a record: the detail is a sibling region, not a route/modal.
9	 */
10	(function () {
11	  const C = window.COLLECTION;
12	  if (!C || !C.items || !C.items.length) {
13	    document.getElementById("results").innerHTML =
14	      '<div class="error-state"><h2>Index failed to load</h2><p>The collection data did not materialize.</p></div>';
15	    return;
16	  }
17	
18	  const DEFAULT_WINDOW = 14;
19	  const WINDOW_STEP = 28;
20	
21	  const state = {
22	    q: "",
23	    facets: { section: new Set(), status: new Set(), era: new Set() },
24	    selectedId: null,
25	    windows: Object.create(null),
26	    focusRowId: null,
27	    focusFacet: null, // `${groupKey}|${value}` to restore after rail re-render
28	  };
29	
30	  const FACETS = [
31	    {
32	      key: "section", label: "Collection", field: "section",
33	      options: C.sections.map((s) => ({ value: s.key, label: s.label })),
34	    },
35	    {
36	      key: "status", label: "Status", field: "status",
37	      options: [
38	        { value: "Digitized", label: "Digitized" },
39	        { value: "In review", label: "In review" },
40	        { value: "On loan", label: "On loan" },
41	      ],
42	    },
43	    {
44	      key: "era", label: "Accession era", field: "era",
45	      options: C.eras.map((e) => ({ value: e.key, label: e.label })),
46	    },
47	  ];
48	
49	  const facetByKey = {};
50	  FACETS.forEach((f) => { facetByKey[f.key] = f; });
51	  const facetValueLabel = {};
52	  FACETS.forEach((f) => f.options.forEach((o) => { facetValueLabel[f.key + "|" + o.value] = o.label; }));
53	
54	  /* ---------- utilities ---------- */
55	
56	  const $ = (sel) => document.querySelector(sel);
57	  const esc = (s) => String(s)
58	    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
59	    .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
60	  const fmt = (n) => n.toLocaleString("en-US");
61	
62	  /* Wrap case-insensitive matches of q in <mark>, on escaped text. */
63	  function highlight(text, q) {
64	    const raw = String(text);
65	    if (!q) return esc(raw);
66	    const lower = raw.toLowerCase();
67	    const ql = q.toLowerCase();
68	    let out = "";
69	    let i = 0;
70	    while (i < raw.length) {
71	      const hit = lower.indexOf(ql, i);
72	      if (hit === -1) { out += esc(raw.slice(i)); break; }
73	      out += esc(raw.slice(i, hit)) + "<mark>" + esc(raw.slice(hit, hit + ql.length)) + "</mark>";
74	      i = hit + ql.length;
75	    }
76	    return out;
77	  }
78	
79	  /* ---------- pipeline ---------- */
80	
81	  function otherFacetsPass(item, skipKey) {
82	    for (const f of FACETS) {
83	      if (f.key === skipKey) continue;
84	      const set = state.facets[f.key];
85	      if (set.size && !set.has(item[f.field])) return false;
86	    }
87	    return true;
88	  }
89	
90	  function compute() {
91	    const q = state.q.trim().toLowerCase();
92	
93	    const base = q ? C.items.filter((it) => it.hay.includes(q)) : C.items;
94	
95	    // Facet counts: candidate set constrained by query and every OTHER group.
96	    const counts = {};
97	    for (const f of FACETS) {
98	      const m = Object.create(null);
99	      for (const o of f.options) m[o.value] = 0;
100	      const pool = base.filter((it) => otherFacetsPass(it, f.key));
101	      for (const it of pool) m[it[f.field]]++;
102	      counts[f.key] = m;
103	    }
104	
105	    const results = base.filter((it) => otherFacetsPass(it, null));
106	
107	    const groups = [];
108	    for (const sec of C.sections) {
109	      const secItems = results.filter((it) => it.section === sec.key);
110	      if (secItems.length) groups.push({ key: sec.key, label: sec.label, items: secItems });
111	    }
112	
113	    return { q, baseCount: base.length, total: results.length, counts: counts, groups: groups };
114	  }
115	
116	  /* ---------- renderers ---------- */
117	
118	  function renderHeader() {
119	    $("#header-totals").textContent =
120	      fmt(C.items.length) + " records · " + C.sections.length + " collections · index rebuilt " + C.rebuilt;
121	  }
122	
123	  function chip(kindLabel, valueLabel, onRemove) {
124	    const el = document.createElement("span");
125	    el.className = "chip";
126	    el.innerHTML =
127	      '<span class="chip-kind">' + esc(kindLabel) + '</span><span class="chip-value">' + esc(valueLabel) + "</span>" +
128	      '<button type="button" class="chip-remove" aria-label="Remove ' + esc(valueLabel) + '">' +
129	      '<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" aria-hidden="true"><line x1="5" y1="5" x2="19" y2="19"/><line x1="19" y1="5" x2="5" y2="19"/></svg>' +
130	      "</button>";
131	    el.querySelector(".chip-remove").addEventListener("click", onRemove);
132	    return el;
133	  }
134	
135	  function renderContext(view) {
136	    const row = $("#context-row");
137	    row.innerHTML = "";
138	
139	    if (view.q) {
140	      row.appendChild(chip("search", "“" + state.q.trim() + "”", () => {
141	        state.q = "";
142	        $("#search-input").value = "";
143	        update(true);
144	        $("#search-input").focus();
145	      }));
146	    }
147	    for (const f of FACETS) {
148	      for (const v of state.facets[f.key]) {
149	        row.appendChild(chip(f.label, facetValueLabel[f.key + "|" + v], () => {
150	          state.facets[f.key].delete(v);
151	          update(true);
152	        }));
153	      }
154	    }
155	
156	    const total = document.createElement("span");
157	    total.className = "result-total";
158	    total.id = "result-total";
159	    total.setAttribute("aria-live", "polite");
160	    const narrowed = view.total !== C.items.length || view.q;
161	    total.innerHTML = narrowed
162	      ? "<strong>" + fmt(view.total) + "</strong> of " + fmt(C.items.length) + " records"
163	      : "<strong>" + fmt(C.items.length) + "</strong> records";
164	    row.appendChild(total);
165	
166	    if (view.q || state.facets.section.size || state.facets.status.size || state.facets.era.size) {
167	      const clear = document.createElement("button");
168	      clear.type = "button";
169	      clear.className = "clear-all";
170	      clear.textContent = "Clear all";
171	      clear.addEventListener("click", () => {
172	        state.q = "";
173	        $("#search-input").value = "";
174	        state.facets.section.clear();
175	        state.facets.status.clear();
176	        state.facets.era.clear();
177	        update(true);
178	      });
179	      row.appendChild(clear);
180	    }
181	  }
182	
183	  function renderFacets(view) {
184	    const rail = $("#filter-rail");
185	    rail.innerHTML = "";
186	
187	    for (const f of FACETS) {
188	      const activeSet = state.facets[f.key];
189	      const group = document.createElement("div");
190	      group.className = "filter-group";
191	
192	      const head = document.createElement("h3");
193	      head.innerHTML = "<span>" + esc(f.label) + "</span>";
194	      if (activeSet.size) {
195	        const gc = document.createElement("button");
196	        gc.type = "button";
197	        gc.className = "group-clear";
198	        gc.textContent = "reset";
199	        gc.setAttribute("aria-label", "Reset " + f.label + " filter");
200	        gc.addEventListener("click", () => {
201	          activeSet.clear();
202	          update(true);
203	        });
204	        head.appendChild(gc);
205	      }
206	      group.appendChild(head);
207	
208	      for (const o of f.options) {
209	        const n = view.counts[f.key][o.value];
210	        const label = document.createElement("label");
211	        label.className = "facet-option" + (n === 0 && !activeSet.has(o.value) ? " off" : "");
212	        const input = document.createElement("input");
213	        input.type = "checkbox";
214	        input.checked = activeSet.has(o.value);
215	        input.addEventListener("change", () => {
216	          state.focusFacet = f.key + "|" + o.value;
217	          if (input.checked) activeSet.add(o.value);
218	          else activeSet.delete(o.value);
219	          update(true);
220	        });
221	        const name = document.createElement("span");
222	        name.className = "opt-label";
223	        name.textContent = o.label;
224	        const count = document.createElement("span");
225	        count.className = "opt-count";
226	        count.textContent = fmt(n);
227	        label.append(input, name, count);
228	        group.appendChild(label);
229	      }
230	      rail.appendChild(group);
231	    }
232	
233	    if (state.focusFacet) {
234	      const [gk, val] = state.focusFacet.split("|");
235	      const f = facetByKey[gk];
236	      if (f) {
237	        const idx = f.options.findIndex((o) => o.value === val);
238	        const inputs = rail.querySelectorAll(".filter-group");
239	        // focus the matching checkbox without scrolling the page
240	        for (const g of inputs) {
241	          const h3 = g.querySelector("h3 span");
242	          if (h3 && h3.textContent === f.label) {
243	            const box = g.querySelectorAll("input")[idx];
244	            if (box) box.focus({ preventScroll: true });
245	            break;
246	          }
247	        }
248	      }
249	      state.focusFacet = null;
250	    }
251	  }
