253	  function rowHtml(it, view) {
254	    const selected = state.selectedId === it.id;
255	    const meta = it.group + " · " + it.locality + " · " + it.date;
256	    return (
257	      '<li><button type="button" class="row" id="row-' + esc(it.id) + '"' +
258	      (selected ? ' aria-current="true"' : "") +
259	      ' data-id="' + esc(it.id) + '">' +
260	      '<span class="dot" data-status="' + esc(it.status) + '" title="' + esc(it.status) + '"></span>' +
261	      '<span class="row-name">' + highlight(it.name, view.q) +
262	      '<span class="common">' + highlight(it.common, view.q) + "</span></span>" +
263	      '<span class="row-id">' + highlight(it.id, view.q) + "</span>" +
264	      '<span class="row-meta">' + esc(meta) + "</span>" +
265	      "</button></li>"
266	    );
267	  }
268	
269	  function renderResults(view) {
270	    const root = $("#results");
271	
272	    if (!view.total) {
273	      root.innerHTML = "";
274	      root.appendChild(zeroState());
275	      return;
276	    }
277	
278	    let html = "";
279	    for (const g of view.groups) {
280	      const shown = Math.min(g.items.length, state.windows[g.key] || DEFAULT_WINDOW);
281	      html += '<section aria-label="' + esc(g.label) + ' results">' +
282	        '<div class="section-head"><h2>' + esc(g.label) + '</h2><span class="sec-count">' +
283	        fmt(g.items.length) + (g.items.length === 1 ? " record" : " records") + "</span></div>" +
284	        "<ol>";
285	      for (let i = 0; i < shown; i++) html += rowHtml(g.items[i], view);
286	      html += "</ol>";
287	      if (shown < g.items.length) {
288	        html += '<button type="button" class="show-more" data-section="' + esc(g.key) + '" ' +
289	          'data-shown="' + shown + '">Show ' + Math.min(WINDOW_STEP, g.items.length - shown) +
290	          " more of " + fmt(g.items.length - shown) + "</button>";
291	      }
292	      html += "</section>";
293	    }
294	    root.innerHTML = html;
295	
296	    root.querySelectorAll(".show-more").forEach((btn) => {
297	      btn.addEventListener("click", () => {
298	        const key = btn.getAttribute("data-section");
299	        state.windows[key] = (state.windows[key] || DEFAULT_WINDOW) + WINDOW_STEP;
300	        update(false);
301	        const again = root.querySelector('.show-more[data-section="' + key + '"]');
302	        if (again) again.focus({ preventScroll: true });
303	      });
304	    });
305	
306	    root.querySelectorAll(".row").forEach((btn) => {
307	      btn.addEventListener("click", () => selectRecord(btn.getAttribute("data-id")));
308	    });
309	  }
