312	    const box = document.createElement("div");
313	    box.className = "zero-state";
314	    box.innerHTML = "<h2>No records match</h2><p>Relax one constraint — the rest of your context stays put.</p>";
315	
316	    const chips = document.createElement("div");
317	    chips.className = "zero-chips";
318	    if (state.q.trim()) {
319	      chips.appendChild(chip("search", "“" + state.q.trim() + "”", () => {
320	        state.q = "";
321	        $("#search-input").value = "";
322	        update(true);
323	      }));
324	    }
325	    for (const f of FACETS) {
326	      for (const v of state.facets[f.key]) {
327	        chips.appendChild(chip(f.label, facetValueLabel[f.key + "|" + v], () => {
328	          state.facets[f.key].delete(v);
329	          update(true);
330	        }));
331	      }
332	    }
