335	  }
336	
337	  function renderDetail() {
338	    const panel = $("#detail-panel");
339	    const shell = $("#workspace");
340	    const it = state.selectedId ? C.items.find((x) => x.id === state.selectedId) : null;
341	
342	    if (!it) {
343	      panel.hidden = true;
344	      panel.innerHTML = "";
345	      shell.classList.remove("has-detail");
346	      return;
347	    }
348	
349	    shell.classList.add("has-detail");
350	    panel.hidden = false;
351	    panel.innerHTML =
352	      '<div class="detail-head">' +
353	      '<h2>' + highlight(it.name, state.q.trim().toLowerCase() || null) + "</h2>" +
354	      '<button type="button" class="detail-close" id="detail-close" aria-label="Close detail, return to results">' +
355	      '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" aria-hidden="true"><line x1="5" y1="5" x2="19" y2="19"/><line x1="19" y1="5" x2="5" y2="19"/></svg>' +
356	      "</button></div>" +
357	      '<p class="detail-common">' + highlight(it.common, state.q.trim().toLowerCase() || null) + "</p>" +
358	      '<div class="detail-idline"><span class="row-id">' + esc(it.id) + "</span>" +
359	      '<span class="status-pill"><span class="dot" data-status="' + esc(it.status) + '"></span>' + esc(it.status) + "</span></div>" +
360	      '<div class="detail-summary">' + esc(it.summary) + "</div>" +
361	      "<dl>" +
362	      "<dt>Taxonomy</dt><dd>" + esc(it.taxa) + "</dd>" +
363	      "<dt>Curatorial group</dt><dd>" + esc(it.group) + "</dd>" +
364	      "<dt>Collected</dt><dd>" + esc(it.date) + " — " + esc(it.locality) + "</dd>" +
365	      "<dt>Collector</dt><dd>" + esc(it.collector) + "</dd>" +
366	      "<dt>Accession era</dt><dd>" + esc(it.eraLabel) + "</dd>" +
367	      "<dt>Catalog number</dt><dd>" + esc(it.id) + "</dd>" +
368	      "</dl>" +
369	      '<div class="tag-row">' + it.tags.map((t) => '<span class="tag">' + esc(t) + "</span>").join("") + "</div>" +
370	      '<p class="provenance">Record ' + esc(it.id) + " · index rebuilt " + esc(C.rebuilt) + " · public-domain data release</p>";
371	
372	    $("#detail-close").addEventListener("click", closeDetail);
373	  }
374	
375	  /* ---------- interactions ---------- */
376	
377	  function selectRecord(id) {
378	    state.selectedId = id;
379	    state.focusRowId = id;
380	
381	    // Update selection affordance in place — the list is not re-rendered,
382	    // so scroll position and focus are untouched by inspection.
383	    document.querySelectorAll('#results .row[aria-current="true"]').forEach((el) => el.removeAttribute("aria-current"));
384	    const row = document.getElementById("row-" + id);
385	    if (row) row.setAttribute("aria-current", "true");
386	
387	    renderDetail();
388	  }
389	
390	  function closeDetail() {
391	    const rowId = state.selectedId;
392	    state.selectedId = null;
393	    renderDetail();
394	    if (rowId) {
395	      const row = document.getElementById("row-" + rowId);
396	      if (row) row.focus({ preventScroll: true });
397	    }
398	  }
399	
400	  function update(renderAll) {
401	    const view = compute();
402	    renderContext(view);
403	    renderFacets(view);
404	    renderResults(view);
405	    if (renderAll) renderDetail();
406	    if (state.focusRowId) {
407	      const row = document.getElementById("row-" + state.focusRowId);
408	      if (row) row.focus({ preventScroll: true });
409	      state.focusRowId = null;
410	    }
411	  }
412	
413	  function boot() {
414	    renderHeader();
415	    update(true);
416	  }
417	
418	  /* ---------- keyboard contract ---------- */
419	
420	  document.addEventListener("keydown", (e) => {
421	    const inInput = /^(input|textarea|select)$/i.test(e.target.tagName);
422	    if (e.key === "/" && !inInput) {
423	      e.preventDefault();
424	      $("#search-input").focus();
425	      $("#search-input").select();
426	    } else if (e.key === "Escape") {
427	      if (e.target.id === "search-input") {
428	        if (state.q) {
429	          state.q = "";
430	          e.target.value = "";
431	          update(true);
432	        } else {
433	          e.target.blur();
434	        }
435	      } else if (state.selectedId) {
436	        closeDetail();
437	      }
438	    }
439	  });
440	
441	  $("#search-input").addEventListener("input", (e) => {
442	    state.q = e.target.value;
443	    update(false);
444	  });
445	
446	  /* First paint is the ready state: data is already materialized. */
447	  try {
448	    boot();
449	  } catch (err) {
450	    const root = document.getElementById("results");
451	    root.innerHTML =
452	      '<div class="error-state"><h2>The index failed to start</h2><p>' +
453	      esc(String(err && err.message ? err.message : err)) +
454	      '</p><button type="button" onclick="location.reload()">Reload the index</button></div>';
455	  }
456	})();
