1	import { readFile, stat } from "node:fs/promises";
2	import { join } from "node:path";
3	import { verifyEvidenceFile } from "prax-runtime";
4	import { captureContracts, captureImplementation, CONTRACT_FILES } from "./measurement-binding.js";
5	import { ARTIFACT_CHECK_IDS, ARTIFACT_CHECK_DEFAULT_SEVERITY, CHECK_MEASUREMENT_MAP, MeasurementReceiptSchema, } from "./contracts.js";
6	const RECEIPT_PREFIX = "validation-evidence/";
7	function invertMap() {
8	    const inverted = new Map();
9	    for (const [checkId, artifactIds] of Object.entries(CHECK_MEASUREMENT_MAP)) {
10	        for (const artifactId of artifactIds) {
11	            const owners = inverted.get(artifactId) ?? [];
12	            owners.push(checkId);
13	            inverted.set(artifactId, owners);
14	        }
15	    }
16	    return inverted;
17	}
18	async function artifactMtime(sessionDirectory, fileName) {
19	    try {
20	        const stats = await stat(join(sessionDirectory, fileName));
21	        return stats.mtime;
22	    }
23	    catch {
24	        return undefined;
25	    }
26	}
27	/**
28	 * Receipt verification and cross-check (spec §5.4). For every evidence item:
29	 * declared receipts are file-verified (containment under
30	 * validation-evidence/), schema-parsed, digest-bound (sha256 recomputed from
31	 * disk — declared values are never trusted), staleness-checked against the
32	 * gated artifacts (§5.7 R3), and cross-checked against claimed outcomes. A
33	 * receipt `fail` contradicting a claimed `pass` BLOCKs; mapped checks passing
34	 * without receipt coverage EXPAND; skipped-with-reason satisfies coverage
35	 * honestly but stays `attested`.
36	 */
37	export async function verifyArtifactEvidence(input) {
38	    const codes = [];
39	    const issues = [];
40	    const warnings = [];
41	    const missingEvidence = [];
42	    const provenanceByCheck = new Map();
43	    const bindingByReceipt = {};
44	    let evidenceCurrent = true;
45	    const addIssue = (code, issue) => {
46	        if (!codes.includes(code))
47	            codes.push(code);
48	        issues.push(`${code}: ${issue}`);
49	    };
50	    const sdirMtime = await artifactMtime(input.sessionDirectory, "screen.sdir.yaml");
51	    const briefMtime = await artifactMtime(input.sessionDirectory, "implementation-brief.yaml");
52	    const newestArtifact = [sdirMtime, briefMtime].reduce((newest, current) => (current !== undefined && (newest === undefined || current > newest) ? current : newest), undefined);
53	    // ── load and verify every declared receipt ──
54	    const loaded = new Map();
55	    for (const item of input.evidence.items) {
56	        if (item.measurement_receipt === undefined)
57	            continue;
58	        const ref = item.measurement_receipt;
59	        if (loaded.has(ref))
60	            continue;
61	        const verified = await verifyEvidenceFile(input.sessionDirectory, ref, RECEIPT_PREFIX);
62	        if (!verified.ok) {
63	            addIssue("EVIDENCE_FILE_INVALID", verified.error);
64	            loaded.set(ref, { ref, receipt: undefined, covering: false });
65	            bindingByReceipt[ref] = "invalid";
66	            evidenceCurrent = false;
67	            continue;
68	        }
69	        let parsed;
70	        try {
71	            parsed = MeasurementReceiptSchema.parse(JSON.parse(await readFile(join(input.sessionDirectory, ref), "utf8")));
72	        }
73	        catch (error) {
74	            addIssue("MEASUREMENT_RECEIPT_INVALID", `${ref} does not parse as a measurement receipt: ${error instanceof Error ? error.message : String(error)}`);
75	            loaded.set(ref, { ref, receipt: undefined, covering: false });
